package com.wenwen.ai.export;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.io.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ExportFieldPolicyTest {
    @Test void sixNaturalMonthsUseShanghaiAndActualColumnSourceDates()throws Exception {
        ExportFieldPolicy policy=new ExportFieldPolicy(6);policy.validate();AiExportQuery q=AiExportQuery.read(new ByteArrayInputStream("{\"source\":\"COHORT\",\"analysisId\":\"00000000-0000-0000-0000-000000000001\",\"fields\":[\"das28Current\"]}".getBytes("UTF-8")));
        ExportFieldPolicy.Window october=new ExportFieldPolicy.Window(Instant.parse("2026-10-07T02:00:00Z"));assertEquals(LocalDate.of(2026,4,1),october.freeStart);assertEquals(LocalDate.of(2026,10,7),october.today);
        assertEquals(LocalDate.of(2026,5,1),new ExportFieldPolicy.Window(Instant.parse("2026-10-31T16:00:00Z")).freeStart);assertEquals(LocalDate.of(2026,7,1),new ExportFieldPolicy.Window(Instant.parse("2027-01-01T00:00:00Z")).freeStart);
        assertEquals(LocalDate.of(2026,5,1),new ExportFieldPolicy.Window(Instant.parse("2026-10-31T16:00:00Z")).freeStart);assertEquals(180,java.time.temporal.ChronoUnit.DAYS.between(LocalDate.of(2026,4,10),LocalDate.of(2026,10,7)));assertFalse(LocalDate.of(2026,4,1).isAfter(october.freeStart));
        List<Map<String,Object>> rows=new ArrayList<>();for(String day:Arrays.asList("2026-04-01","2026-03-31",null,"2026-10-08")){Map<String,Object> row=new LinkedHashMap<>();row.put("selection",Collections.singletonMap("nowDate",day));rows.add(row);}List<Map<String,Object>> blocked=policy.blocked(q,Collections.singletonMap("rows",rows),october);assertEquals(3,blocked.size());assertEquals(Arrays.asList("MISSING_SOURCE_DATE","SOURCE_BEFORE_WINDOW","SOURCE_AFTER_TODAY"),Arrays.asList(blocked.get(0).get("reason"),blocked.get(1).get("reason"),blocked.get(2).get("reason")));for(Map<String,Object> b:blocked){assertEquals(1,b.get("affectedN"));assertNull(b.get("side"));}
        assertTrue(policy.blocked(q,Collections.singletonMap("rows",Collections.singletonList(rows.get(0))),october).isEmpty());
        ExportFieldPolicy.Window november=new ExportFieldPolicy.Window(Instant.parse("2026-10-31T16:00:00Z"));assertEquals(183,java.time.temporal.ChronoUnit.DAYS.between(LocalDate.of(2026,5,2),november.today));assertTrue(policy.blocked(q,Collections.singletonMap("rows",Collections.singletonList(Collections.singletonMap("selection",Collections.singletonMap("nowDate","2026-05-01")))),november).isEmpty());
    }
    @Test void aggregateWindowReasonsUseWholeValidNAndKeepIndependentMissingReason()throws Exception {
        ExportFieldPolicy policy=new ExportFieldPolicy(6);AiExportQuery q=AiExportQuery.read(new ByteArrayInputStream("{\"source\":\"COMPARE\",\"compareResultId\":\"00000000-0000-0000-0000-000000000001\",\"metrics\":[\"crpAt\"]}".getBytes("UTF-8")));ExportFieldPolicy.Window w=new ExportFieldPolicy.Window(Instant.parse("2026-10-07T02:00:00Z"));Map<String,Object> c=new LinkedHashMap<>();c.put("validN",3);c.put("datedN",2);c.put("undatedN",1);c.put("missingN",3);c.put("minDate","2026-03-31");c.put("maxDate","2026-10-08");c.put("status","PARTIAL");Map<String,Object> coverage=new LinkedHashMap<>();coverage.put("a",Collections.singletonMap("crpAt",c));coverage.put("b",Collections.emptyMap());Map<String,Object> p=new LinkedHashMap<>();p.put("a",Collections.singletonMap("n",6));p.put("b",Collections.singletonMap("n",0));p.put("meta",Collections.singletonMap("sourceDateCoverage",coverage));List<Map<String,Object>> blocked=policy.blocked(q,p,w);assertEquals(3,blocked.size());assertEquals(Arrays.asList("MISSING_SOURCE_DATE","SOURCE_BEFORE_WINDOW","SOURCE_AFTER_TODAY"),Arrays.asList(blocked.get(0).get("reason"),blocked.get(1).get("reason"),blocked.get(2).get("reason")));assertEquals(1,blocked.get(0).get("affectedN"));assertEquals(3,blocked.get(1).get("affectedN"));assertEquals(3,blocked.get(2).get("affectedN"));for(Map<String,Object> b:blocked){assertEquals("A",b.get("side"));assertEquals("crpAt",b.get("field"));}
        c.put("validN",0);c.put("datedN",0);c.put("undatedN",0);c.put("missingN",6);c.put("minDate",null);c.put("maxDate",null);c.put("status","NO_DATA");blocked=policy.blocked(q,p,w);assertEquals(1,blocked.size());assertEquals("NO_VALID_CONTRIBUTION",blocked.get(0).get("reason"));assertEquals(6,blocked.get(0).get("affectedN"));p.put("a",Collections.singletonMap("n",0));assertTrue(policy.blocked(q,p,w).isEmpty());
    }
}
